// Ajouter un cours : une entrée COURSE, des chapitres et des questions référencées.
// Le lecteur et les filtres sont construits à partir de ces données.
const section=(title,text,extra={})=>({title,text,...extra});
const chapter=(id,title,kicker,summary,structures,sections,extra={})=>({id,title,kicker,summary,structures,sections,...extra});
export const COURSES=[
{id:'c1',number:'01',title:'Les bases du cerveau',subtitle:'Observer, se repérer et suivre l’information',source:'./assets/cours.txt',chapters:[
chapter('c1-observer','Comment observer le cerveau ?','Imagerie et activité','Distinguer une image de l’anatomie d’une mesure de l’activité.',['irm','scanner','tractography','fmri','eeg','meg'],[
section('Des outils complémentaires','L’IRM montre l’anatomie grâce à un champ magnétique et des signaux de résonance. Le scanner utilise des rayons X. La tractographie estime des trajets de substance blanche à partir de l’IRM de diffusion ; elle ne photographie pas chaque axone.'),
section('Mesurer l’activité','L’EEG enregistre des signaux électriques ; la MEG mesure les champs magnétiques associés. Des électrodes intracrâniennes rapprochent l’enregistrement des régions étudiées. L’IRMf mesure un signal indirect, le BOLD, lié à l’oxygénation sanguine.'),
section('Interpréter une carte','Une différence de signal entre deux conditions ne signifie pas que les autres régions sont éteintes. Le cerveau utilise de nombreux réseaux au fil du temps : le mythe des « 10 % » est faux. La plasticité décrit la modification de circuits avec l’expérience, tout au long de la vie.')
],{takeaway:'Anatomie, connexions et activité : trois questions, plusieurs outils.',table:{headers:['Question','Outils du cours'],rows:[['Quelle forme ?','IRM, scanner'],['Quelles connexions estimées ?','IRM de diffusion / tractographie'],['Quand et où l’activité varie-t-elle ?','EEG, MEG, électrodes, IRMf']]}}),
chapter('c1-reperes','Se repérer dans le cerveau','Lobes, plis et plans','Nommer les grands territoires et distinguer un relief d’un creux.',['frontal','parietal','temporal','occipital','insula','central','precentral','postcentral'],[
section('Une enveloppe et deux hémisphères','Le cortex est la couche de substance grise plissée à la surface des hémisphères. Il s’étend aussi sur leurs faces médiales et inférieures. Un gyrus est un relief ; un sillon est un creux. Le corps calleux relie les hémisphères par des axones.'),
section('Quatre lobes visibles, une insula enfouie','Frontal : à l’avant. Pariétal : derrière le sillon central. Temporal : sous le sillon latéral. Occipital : à l’arrière. L’insula est cachée au fond du sillon latéral, mais reste du cortex.'),
section('Le repère central','Le gyrus précentral, devant le sillon central, repère M1. Le gyrus postcentral, derrière, repère S1. Un nom anatomique décrit une position ; une aire fonctionnelle décrit des traitements. Leurs limites ne coïncident pas toujours.'),
section('Lire une coupe','Sagittal : sépare droite et gauche. Coronal : parallèle au front, sépare avant et arrière. Axial ou horizontal : sépare haut et bas. Dans les coupes IRM de l’atlas, D et G désignent les côtés de la personne, pas ceux de l’écran.')
],{figure:'lobes',takeaway:'Devant le sillon central : mouvement. Derrière : sensibilité.'}),
chapter('c1-tissus','Tissus, neurones et ventricules','Du cerveau à la cellule','Comprendre ce qui traite, ce qui relie et ce qui contient le liquide.',['grey','white','callosum','ventricles','choroid','neuron'],[
section('Substance grise et substance blanche','La substance grise est riche en corps cellulaires, dendrites et synapses ; elle existe dans le cortex et dans des noyaux profonds. La substance blanche contient surtout des axones, souvent myélinisés, ainsi que des cellules gliales.'),
section('Un neurone, plusieurs territoires','Les dendrites reçoivent de nombreux signaux ; le soma assure le fonctionnement cellulaire et participe à l’intégration. L’axone conduit les potentiels d’action, et les terminaisons transmettent aux cellules cibles. La myéline accélère la conduction. Tous les neurones n’ont pas la même forme.'),
section('Ventricules et LCR','Les ventricules sont des cavités contenant du liquide céphalorachidien (LCR), produit principalement par les plexus choroïdes. Il circule aussi autour du cerveau et de la moelle. Il contribue à la protection mécanique et à l’environnement du système nerveux. Une hydrocéphalie correspond à une dilatation ventriculaire liée à un trouble de sa dynamique.')
],{takeaway:'Grise → traitement ; blanche → communication : un mémo, pas une séparation absolue.',exercise:'td',figure:'neuron'}),
chapter('c1-voir-entendre','Vision et audition','Des récepteurs aux réseaux','Suivre V1 et A1, puis les traitements secondaires et associatifs.',['v1','visualSecondary','visualAssociation','a1','a2','auditoryAssociation'],[
section('La logique sensorielle','Transduction : un stimulus devient un signal neuronal. Transmission : le signal parcourt des voies. Relais et traitements : l’information rejoint des territoires corticaux primaires, secondaires et associatifs. Cette progression aide à apprendre, mais les réseaux réels comportent des voies parallèles et des retours.'),
section('Vision','Lumière → photorécepteurs rétiniens → cellules ganglionnaires et nerf optique → chiasma → relais thalamique, notamment le corps genouillé latéral → V1. V1 se situe autour du sillon calcarin, sur la face médiale occipitale. Des régions visuelles traitent ensuite formes, couleurs, mouvement et reconnaissance.'),
section('Reconnaître un visage','Les réseaux occipito-temporaux, dont des régions du gyrus fusiforme, participent à reconnaître les visages. Une prosopagnosie concerne cette reconnaissance et ne signifie pas nécessairement une mauvaise vision élémentaire. Une lésion bilatérale importante de V1 peut au contraire produire une cécité corticale.'),
section('Audition','Vibration → tympan et osselets → cochlée et cellules sensorielles → nerf auditif → relais du tronc cérébral → thalamus, notamment le corps genouillé médial → A1. A1 se repère dans les gyri transverses de Heschl. Les régions auditives secondaires (« A2 » dans le cours) et associatives analysent des sons plus complexes.'),
section('À propos des perceptions anormales','Des activités anormales de réseaux sensoriels peuvent contribuer à des hallucinations. Une hallucination ne permet pas, à elle seule, de localiser une lésion ou un foyer précis. Les exemples du cours illustrent des liens, pas une règle diagnostique.')
],{takeaway:'V1 : repère occipital médial. A1 : repère temporal supérieur enfoui.',circuits:['vision','audition']}),
chapter('c1-sentir','Le corps, le goût et les odeurs','Sensibilité et exceptions','Comprendre S1 et l’exception olfactive.',['s1','somaticAssociation','insula','thalamus','olfaction'],[
section('Somesthésie','Toucher, pression, température, douleur et informations sur la position du corps proviennent de différents récepteurs. Ils rejoignent des voies sensitives puis le thalamus et des territoires corticaux. S1, surtout dans le gyrus postcentral, traite notamment leur modalité, leur intensité et leur localisation.'),
section('La carte du corps','L’homoncule sensoriel représente une organisation somatotopique. La place d’une partie du corps reflète son traitement sensoriel, pas sa taille réelle. Les mains et le visage occupent une grande surface ; le membre inférieur est plus médial. Les projections sont principalement controlatérales.'),
section('Goût et olfaction','Les récepteurs gustatifs conduisent vers des relais, dont le thalamus, puis vers un cortex gustatif impliquant l’insula et l’opercule. L’olfaction atteint d’abord le cortex olfactif primaire via le bulbe, sans relais thalamique obligatoire préalable ; le thalamus intervient dans des traitements ultérieurs.'),
section('Percevoir dépend aussi des récepteurs','Les espèces ne détectent pas toutes les mêmes stimuli. La perception humaine ne représente pas toutes les propriétés physiques du monde ; elle dépend des capteurs et des traitements du système nerveux.')
],{takeaway:'S1 est principalement controlatéral ; l’olfaction est l’exception au relais thalamique préalable.',circuits:['touch','taste','smell']}),
chapter('c1-mouvement','De l’intention au mouvement','Préparation et exécution','Distinguer les aires motrices secondaires de M1.',['dlpfc','m2','premotor','sma','m1','s1','somaticAssociation','spinal','muscles'],[
section('Choisir et préparer','Les réseaux préfrontaux participent aux objectifs et à la décision. Les régions prémotrices latérales et l’aire motrice supplémentaire (SMA / AMS) contribuent à préparer et organiser l’action. Ce sont des interactions, pas une chaîne rigide qui s’active une seule fois.'),
section('M2, prémoteur et SMA','Le cours peut employer « cortex moteur secondaire » ou M2. Chez l’humain, retiens plusieurs aires, notamment le prémoteur latéral et la SMA médiale, principalement dans l’aire 6. La notation M2 varie et est courante dans les atlas de rongeurs ; elle ne désigne pas partout une aire humaine unique.',{precision:'Le repère 3D de la SMA couvre le gyrus frontal supérieur, plus étendu que la SMA. Le contour montre ce repère anatomique, pas une frontière fonctionnelle exacte.'}),
section('Lire l’image et les retours sensoriels','L’image fournie réunit des vues latérale et médiale. Elle distingue M1 en rouge, le prémoteur en bleu et la SMA en violet. S1 apporte des informations corporelles ; les régions pariétales postérieures, dont les aires 5 et 7 indiquées, participent à leur intégration pour l’action. Le préfrontal dorsolatéral contribue aux objectifs et au contrôle. Ces régions coopèrent : les couleurs ne représentent pas une série rigide d’étapes ni des frontières fonctionnelles exactes.'),
section('Exécuter','M1 se repère au gyrus précentral. Ses voies descendantes contribuent au contrôle de circuits moteurs du tronc cérébral et de la moelle. Les motoneurones commandent les muscles. Le contrôle est principalement controlatéral : hémisphère gauche → côté droit du corps.'),
section('Stimuler et communiquer','La stimulation magnétique transcrânienne peut modifier l’activité corticale et produire une réponse motrice selon son site et son intensité. Les interfaces cerveau-machine apprennent des correspondances entre signaux cérébraux et actions ou intentions. Elles ne lisent pas librement toutes les pensées.')
],{figure:'motorCortices',takeaway:'Préfrontal → objectifs ; prémoteur / SMA → préparation ; M1 → commande descendante.',circuits:['movement'],sources:['motor']})
]},
{id:'c2',number:'02',title:'Régions et grandes fonctions',subtitle:'Attention, mémoire, mouvement et équilibre du corps',source:'./assets/cours-2.txt',chapters:[
chapter('c2-attention','Contrôler et orienter l’attention','Préfrontal et réseaux','Comprendre les fonctions exécutives et les pensées internes.',['prefrontal','dlpfc','associative','parietal'],[
section('Trois familles de traitements','Des cortex sensoriels analysent les informations reçues ; des cortex moteurs participent à l’action. Des territoires associatifs relient ces informations au contexte, aux connaissances et aux objectifs. Ces catégories interagissent et ne constituent pas des compartiments fermés.'),
section('Les fonctions exécutives','Maintenir un objectif en mémoire de travail, résister à un distracteur, inhiber une réponse, changer de règle, planifier et résoudre un problème : autant de fonctions de contrôle. Elles permettent d’adapter un comportement au lieu de suivre automatiquement une impulsion.'),
section('Préfrontal dorsolatéral','Le DLPFC contribue notamment à la mémoire de travail, au maintien des objectifs et à l’attention. L’inhibition mobilise aussi d’autres régions frontales et des circuits sous-corticaux. La fatigue, le manque de sommeil et l’anxiété peuvent modifier les performances ; le développement du contrôle se poursuit avec la maturation.',{precision:'Le DLPFC n’est pas un frein unique qui bloque à lui seul tous les distracteurs et toutes les actions.'}),
section('Réseau du mode par défaut','Le DMN participe à des pensées orientées vers l’intérieur : souvenirs, projection dans le futur, réflexion sur soi. Quand on se concentre sur une tâche externe, son activité peut diminuer. Il échange avec les réseaux d’attention et de contrôle ; il n’est pas seulement un réseau de rumination ou un adversaire à supprimer.'),
section('Une attention sélective','Compter des passes dans une vidéo peut faire manquer un événement inattendu : c’est la cécité d’inattention. On sélectionne certains signaux au détriment d’autres. Ne pas remarquer un élément ne prouve pas que les yeux n’ont rien reçu.')
],{takeaway:'Contrôler = maintenir un objectif et adapter sa sélection d’informations.',example:'Tu cherches tes clés tout en repensant à une discussion : la tâche et les pensées internes sollicitent des réseaux en interaction.'}),
chapter('c2-espace-langage','Espace et langage','Pariétal, Broca et Wernicke','Distinguer un trouble attentionnel d’un trouble visuel ; comprendre les repères du langage.',['parietal','somaticAssociation','broca','wernicke'],[
section('Orienter l’attention dans l’espace','Les régions pariétales et leurs connexions participent à la représentation de l’espace, à la sélection des informations et à l’action. Le réseau d’attention implique aussi des régions frontales et sous-corticales.'),
section('Héminégligence','Une lésion de réseaux droits, souvent pariétaux, peut entraîner une négligence de l’espace gauche : aliments laissés d’un côté de l’assiette, omission d’une partie d’un dessin. Ce n’est pas simplement une perte du champ visuel.',{precision:'« Lésion pariétale droite → héminégligence gauche » est un repère classique, pas une conséquence obligatoire de toute lésion pariétale.'}),
section('Les repères classiques du langage','Broca, dans le frontal inférieur dominant, est un repère pour la production. Wernicke, classiquement dans le temporal supérieur postérieur dominant, est un repère pour la compréhension. L’hémisphère dominant est le plus souvent gauche.'),
section('Un réseau, plusieurs composantes','La production, la compréhension, la lecture et la répétition s’appuient sur des territoires et des connexions distribués. Une aphasie de Broca peut comporter des difficultés de compréhension syntaxique. La distinction Broca / Wernicke aide à commencer, mais ne résume pas toutes les aphasies.')
],{figure:'lobes',takeaway:'Héminégligence : attention spatiale. Aphasie : langage. Deux mécanismes à distinguer.',sources:['language','neglect']}),
chapter('c2-memoire','Mémoire et valeur émotionnelle','Hippocampe et amygdale','Former un souvenir et apprendre l’importance d’un événement.',['hippocampus','amygdala','temporal','prefrontal'],[
section('Le « système limbique »','Ce terme regroupe historiquement des structures associées à la mémoire, à la motivation et aux émotions. Leurs limites et leurs fonctions se recouvrent avec d’autres réseaux. Il ne s’agit pas d’un petit cerveau émotionnel autonome séparé du cortex.'),
section('L’hippocampe','Il se situe dans le temporal médial et contribue à former des souvenirs déclaratifs, notamment des événements situés dans un contexte spatial et temporel. Il participe aussi à la navigation. La mémoire implique des systèmes multiples ; les souvenirs ne sont pas tous stockés dans l’hippocampe.'),
section('Ce que montre le cas H.M.','Après une résection temporale médiale bilatérale, H.M. présentait une difficulté majeure à former de nouveaux souvenirs déclaratifs, tandis que certains apprentissages procéduraux restaient possibles.',{precision:'La résection concernait une partie des hippocampes et des structures voisines, dont des régions amygdaliennes et corticales. Il restait du tissu hippocampique : les deux hippocampes n’avaient pas été retirés intégralement.'}),
section('Alzheimer : un lien, pas un diagnostic','Des régions temporales médiales, dont l’hippocampe, peuvent être précocement affectées. Les difficultés peuvent concerner les souvenirs récents. La maladie évolue et touche des réseaux plus larges ; tout oubli quotidien n’indique pas une maladie d’Alzheimer.'),
section('L’amygdale','Elle est en avant de l’hippocampe. Elle participe à l’apprentissage émotionnel et à l’évaluation de signaux importants, dont les menaces. Une atteinte bilatérale peut perturber certains apprentissages et la reconnaissance de la peur.',{precision:'L’amygdale intervient aussi dans des associations positives et de récompense. « Alarme » aide à retenir un exemple ; elle ne se limite pas aux émotions négatives.'})
],{figure:'limbic',takeaway:'Hippocampe → nouveaux souvenirs ; amygdale → valeur émotionnelle apprise.',sources:['hm','amygdala']}),
chapter('c2-boucles','Relais, actions et habitudes','Thalamus et ganglions de la base','Comprendre des boucles qui sélectionnent et régulent l’information et l’action.',['thalamus','basalGanglia','m2','m1'],[
section('Le thalamus','De chaque côté du troisième ventricule se trouve un ensemble de noyaux thalamiques. Ils participent à des relais et à des boucles sensorielles, motrices, cognitives et attentionnelles.',{precision:'On parle de deux masses thalamiques contenant plusieurs noyaux, et non de seulement deux grands noyaux isolés.'}),
section('Conscience et absences','Les interactions thalamo-corticales et les réseaux d’éveil contribuent à l’état conscient. Les crises d’absence impliquent une activité anormale de réseaux, avec une altération transitoire de la réponse et de la conscience. Une apparente distraction ne suffit pas à identifier une crise.'),
section('Les ganglions de la base','Le cours cite le noyau caudé, le putamen, le pallidum, le noyau sous-thalamique et la substance noire. Le caudé et le putamen forment le striatum dorsal. Leurs circuits en boucle avec le cortex et le thalamus participent à la sélection d’actions et à la régulation du mouvement.'),
section('De l’apprentissage à l’habitude','Apprendre à conduire demande d’abord beaucoup de contrôle conscient. Certaines séquences deviennent plus automatiques avec l’entraînement. Les ganglions de la base contribuent aux habitudes et à des apprentissages procéduraux, sans être l’unique siège de tous les automatismes.'),
section('Parkinson et Tourette','Dans Parkinson, la perte de neurones dopaminergiques de la substance noire perturbe les circuits moteurs : lenteur, rigidité et parfois tremblement. La stimulation cérébrale profonde peut aider certains patients sélectionnés, sans guérir la maladie. Dans Tourette, des réseaux cortico-striato-thalamo-corticaux participent aux tics ; ce n’est pas un simple automatisme volontaire.')
],{figure:'basal',takeaway:'Thalamus → relais et modulation ; ganglions de la base → sélection et apprentissage de l’action.',sources:['basal']}),
chapter('c2-homeostasie','Maintenir l’équilibre du corps','Hypothalamus, hypophyse et système autonome','Relier besoins du corps, hormones et régulations végétatives.',['hypothalamus','pituitary','thalamus','amygdala'],[
section('L’hypothalamus','Sous le thalamus, il participe à l’homéostasie : faim, soif, température, rythmes et réponses au stress. Il coordonne des réponses hormonales, autonomes et comportementales.'),
section('L’axe hypothalamo-hypophysaire','L’hypothalamus est relié à l’hypophyse. Il régule une partie de ses sécrétions et des axes endocriniens, notamment liés au stress et à la reproduction. Hypothalamus et hypophyse ne sont pas synonymes.'),
section('Sympathique et parasympathique','Le sympathique contribue à mobiliser des ressources, par exemple en accélérant le cœur dans une situation de menace. Le parasympathique contribue notamment à la régulation cardiaque et digestive. Tous deux assurent en permanence des fonctions autonomes ; leurs effets dépendent de l’organe.',{precision:'« Action / repos » est un mémo. Le parasympathique ne s’allume pas uniquement après un danger, et les deux systèmes ne produisent pas toujours des effets strictement opposés.'})
],{figure:'diencephalon',takeaway:'Sous le thalamus : hypothalamus ; reliée en dessous : hypophyse.'}),
chapter('c2-coordination','Ajuster et apprendre un geste','Le cervelet','Comparer les commandes aux retours sensoriels.',['cerebellum','m1','m2','basalGanglia'],[
section('Où et avec quelles informations ?','Le cervelet se trouve derrière le tronc cérébral, sous les régions occipitales. Il reçoit des informations liées aux commandes motrices et aux retours somatosensoriels, vestibulaires et visuels.'),
section('Coordonner et adapter','Il contribue à prédire les conséquences d’un mouvement, à coordonner sa précision et son timing, et à apprendre à partir des erreurs. L’idée « prévu ↔ réalisé » aide à comprendre ses fonctions, sans faire de lui un comparateur unique de toutes les actions.'),
section('Exemple et lésion','À la fléchette, les erreurs des premiers essais permettent d’ajuster progressivement le geste. Une atteinte cérébelleuse peut entraîner une ataxie et des difficultés de précision ou d’équilibre. Le test doigt-nez illustre l’évaluation de la coordination.')
],{figure:'lobes',takeaway:'Préparer ≠ sélectionner ≠ coordonner : prémoteur / SMA, ganglions de la base et cervelet coopèrent.',table:{headers:['Repère','Contribution à retenir'],rows:[['Prémoteur / SMA','Préparation et organisation'],['Ganglions de la base','Sélection et habitudes'],['M1','Commande motrice descendante'],['Cervelet','Coordination et adaptation']]},circuits:['movement']}),
chapter('c2-eveil','Éveil, fonctions vitales et communication','Le tronc cérébral','Comprendre pourquoi immobilité et inconscience sont différentes.',['brainstem','cerebellum','thalamus','bci'],[
section('Trois étages','Le tronc cérébral comprend le mésencéphale, le pont et le bulbe rachidien. Il relie le cerveau à la moelle, contient de nombreuses voies et des noyaux de nerfs crâniens. Le cervelet est attaché à ses circuits, mais reste une structure distincte.'),
section('Éveil et régulations vitales','Des réseaux du tronc contribuent à l’éveil, à la respiration et au contrôle cardiovasculaire. Une lésion peut être grave, selon sa localisation et son étendue. La conscience repose sur des interactions avec le thalamus et le cortex, pas sur un seul centre isolé.'),
section('Locked-in syndrome','Dans la forme classique, une lésion du pont ventral peut provoquer une paralysie majeure et empêcher la parole, alors que la conscience est préservée. Des mouvements oculaires ou des clignements peuvent permettre la communication. D’autres formes existent.'),
section('Jean-Dominique Bauby','L’auteur du Scaphandre et le Papillon a dicté son livre par clignements d’une paupière. Des interfaces cerveau-machine cherchent aussi à rétablir une communication à partir de signaux cérébraux.',{precision:'Le prénom complet est Jean-Dominique Bauby. Un patient immobile ne doit pas être assimilé automatiquement à un patient inconscient.'})
],{figure:'brainstem',takeaway:'Motricité, capacité de répondre et conscience doivent être distinguées.',sources:['locked']})
]}
];
COURSES.push(NEURON_COURSE,SYNAPSE_COURSE);
